        move    #>$ffcc99,n5
        mpy     y0,x0,b       #>$4ccccd,y1; s = absorb * d; g
        move    b,x0
        mac     -x0,y1,a                ; w = x - g*s
        move    a,y:(r5+n5)
        move    #>$ffc808,n5
        move    a,x0
        mac     x0,y1,b                 ; y = s + g*w
        move    y:(r5+n5),x0            ; AP6R 701, g=0.6
        move    #>$ffcac5,n5
        mpy     y0,x0,a       #>$4ccccd,y1; s = absorb * d; g
        move    a,x0
        mac     -x0,y1,b                ; w = x - g*s
        move    b,y:(r5+n5)
        move    #>$ffc807,n5
        move    b,x0
        mac     x0,y1,a                 ; y = s + g*w
        move    a,y:(r5+n5)             ; LATE into the loop delay 1733 + depth - e
        move    x:(r7+$21),b            ; wR = early + diff*(late - early)
        sub     b,a
        move    a,x0
        move    x:(r7+$43),y1
