        asr     #$8,a,a                 ; the moving read: a1 the integer, a0 the fraction << 16
        move    a1,n5                   ; the ring offset of the older word
        move    a0,b
        lsr     b                       ; b1 = f << 15, non-negative; b2 is stale
        lua     (r5+n5),r4
        move    b1,y0                   ; f, the fraction toward the newer word
        move    x:(r7+$22),x1           ; wl, for the output
        move    y:(r4)+,b
        move    y:(r4),a
        sub     b,a
        move    a,x0
        mpy     y0,x0,a
        add     b,a
        move    a,x:(r7+$1d)            ; L has read it
; ---- output: L = A*wl + B*wr + D*dryL, R = A*wr + B*wl + D*dryR, /8 ----
        move    x:(r7+$23),x0           ; wr; wl is in x1
        move    x:(r7+$44),y0
        move    x:(r7+$45),y1
        mpy     x1,y0,a                 ; A*wl
        mac     x0,y1,a                 ; + B*wr
