        mac     y1,x1,b                 ; + B*wl
        move    x:(r7+$46),y0
        move    x:(r0),x0               ; dry
        mac     y0,x0,a
        asl     #$3,a,a                 ; x8; the store limits: the output clip
        move    a,x:(r0)+
        move    x:(r0),x0               ; dry
        mac     y0,x0,b
        asl     #$3,b,b                 ; x8; the store limits: the output clip
        move    b,x:(r0)+
